"""Loads the bundled tool catalog (generated by scripts/build_catalog.py)."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import lru_cache
from importlib import resources
from typing import Any

from panda_federation_tools.config import MAX_CHARGE_USD, MAX_ITEMS, MAX_TIMEOUT_SECS

RUN_OPTIONS: dict[str, dict[str, Any]] = {
    "run_max_items": {
        "type": "integer",
        "minimum": 1,
        "maximum": MAX_ITEMS,
        "description": "Optional. Most results to return from this call (default from PANDA_MAX_ITEMS, 50).",
    },
    "run_max_charge_usd": {
        "type": "number",
        "minimum": 0.01,
        "maximum": MAX_CHARGE_USD,
        "description": "Optional. Hard spending cap for this call in USD (default from PANDA_MAX_CHARGE_USD, 0.50).",
    },
    "run_timeout_secs": {
        "type": "integer",
        "minimum": 10,
        "maximum": MAX_TIMEOUT_SECS,
        "description": "Optional. Seconds to wait for results (default from PANDA_TIMEOUT_SECS, 120; max 300).",
    },
}


@dataclass(frozen=True)
class ToolSpec:
    name: str
    actor: str
    title: str
    description: str
    url: str
    pricing: tuple[dict[str, Any], ...]
    actor_schema: dict[str, Any]

    @property
    def price_text(self) -> str:
        parts = [f"${p['usd']:g} per {p['title'].lower()}" for p in self.pricing if p.get("usd") is not None]
        return "; ".join(parts) if parts else "see the Apify page"

    @property
    def input_schema(self) -> dict[str, Any]:
        """Actor inputs plus the shared run_* options, as a JSON Schema object."""
        schema: dict[str, Any] = json.loads(json.dumps(self.actor_schema))
        schema["properties"].update(json.loads(json.dumps(RUN_OPTIONS)))
        return schema

    @property
    def tool_description(self) -> str:
        return (
            f"{self.description}\n\nRuns the Apify Actor {self.actor} ({self.url}) on your own Apify account. "
            f"Price: {self.price_text}. Runs that find nothing are not charged per result. "
            "Spending is capped per call by run_max_charge_usd."
        )


@lru_cache(maxsize=1)
def load_catalog() -> tuple[ToolSpec, ...]:
    raw = resources.files("panda_federation_tools").joinpath("catalog.json").read_text(encoding="utf-8")
    data = json.loads(raw)
    return tuple(
        ToolSpec(
            name=t["name"],
            actor=t["actor"],
            title=t["title"],
            description=t["description"],
            url=t["url"],
            pricing=tuple(t.get("pricing") or ()),
            actor_schema=t["inputSchema"],
        )
        for t in data["tools"]
    )


def get_tool(name: str) -> ToolSpec | None:
    return next((t for t in load_catalog() if t.name == name), None)
